Lemma poison_bytes_app : forall a b v, poison_bytes (a + b) v = poison_bytes a v ++ poison_bytes b v.
Proof. intros. unfold poison_bytes. apply repeat_app. Qed.
Lemma poison_bytes_length : forall a v, length (poison_bytes a v) = a.
Proof. intros. unfold poison_bytes. apply repeat_length. Qed.

