  /\ cc_shadow len n = poison_bytes (Z.to_nat (o / 8)) 0 ++ (poison_bytes (Z.to_nat ((n - o) / 8)) 0 ++ poison_bytes (Z.to_nat ((len - n) / 8)) 0xfc).
